query EntityOverview($key: ID!, $role: Role!, $filter: RecordFilter) {
  entity(key: $key) {
    ...EntityHeaderFields
    seap {
      role(role: $role) {
        role
        total(filter: $filter) {
          ...TotalFields
        }
        counterparties(filter: $filter, limit: 10) {
          count
          topShare
          rows {
            entity {
              ...EntityRef
            }
            naturalPerson
            total {
              ...TotalFields
            }
          }
        }
        directPurchaseShare(filter: $filter)
        procedures(filter: $filter) {
          value
          total {
            ...TotalFields
          }
        }
        consortia(filter: $filter, limit: 10) {
          members {
            ...PartyFields
          }
          total {
            ...TotalFields
          }
        }
        frameworks(filter: $filter) {
          count
          ceilings
          subsequentReported
        }
        largestRecords(filter: $filter, limit: 10) {
          ...RecordRowFields
        }
        signals(filter: $filter, limit: 20) {
          count
          rows {
            ...SignalFields
          }
        }
      }
    }
  }
}

fragment EntityHeaderFields on Entity {
  ...EntityRowFields
  cui
  foreignVatId
  identityCurated
  aliases {
    name
    records
    first
    last
    differsFromAnaf
