            naturalPerson
            total {
              ...TotalFields
            }
            viaDirectPurchase {
              ...TotalFields
            }
            viaContract {
              ...TotalFields
            }
            wonTogether
            hasSignals
          }
        }
        timeline(filter: $filter, counterparty: $counterparty) {
          month
          total {
            ...TotalFields
          }
        }
        flow(filter: $filter) {
          ...MoneyMapFields
