query MainScreen($filter: RecordFilter!, $side: CountySide) {
  sources {
    ...DataThroughFields
  }
  seap {
    search(filter: $filter) {
      filter {
        qFolded
        authority {
          ...EntityRef
        }
        supplier {
          ...EntityRef
        }
      }
      total {
        ...TotalFields
      }
      map(side: $side) {
        ...MoneyMapFields
      }
      goTo {
        ...EntityRef
      }
      authorities(limit: 50) {
        count
        countEstimated
        rows {
          entity {
            ...EntityRowFields
          }
          matched {
            ...TotalFields
          }
        }
      }
      suppliers(limit: 50) {
        count
        countEstimated
        rows {
          entity {
            ...EntityRowFields
          }
          matched {
            ...TotalFields
          }
        }
      }
      records(limit: 50) {
        count
        rows {
          record {
            ...RecordRowFields
          }
          matchedField {
            field
            text
            highlights
          }
        }
      }
    }
  }
}

