query ZoomedCounty($filter: RecordFilter!, $county: CountyCode!, $side: CountySide) {
  uats(county: $county) {
    siruta
    name
    county {
      code
      name
    }
  }
  seap {
    search(filter: $filter) {
      total {
        ...TotalFields
      }
      uatMap(county: $county, side: $side) {
        uats {
          area
          name
          entities
          total {
            ...TotalFields
          }
        }
        unknownUat {
          ...TotalFields
        }
      }
    }
  }
}

